// GENERATED by build.sh -- edit tests/canvas2d-text/test.js, not this file.
// Conformance harness: how a test says what it found.
//
// The result channel is `console.error` with a structured prefix. That looks
// crude and it is the deliberate choice: it is the ONE channel that already
// works identically on every platform Migo runs on -- Android through JNI,
// C-ABI hosts with no JVM, the Linux player, Windows -- with no new platform
// surface to build, maintain, or forget to port. (`console.log` is filtered by
// EMUI on real Huawei devices; `console.error` is not.)
//
// Everything below is deliberately dependency-free and runs inside the game
// bundle, because the whole point is that the same bundle produces the same
// verdict wherever it runs.
//
// The API these bundles call is `migo.*`, not `wx.*`. `migo` is the only
// capability surface the engine installs; the mini-game-platform globals come
// from a separate adapter package that a host loads if it wants them. Bundles
// here written against `wx` stopped running entirely when that namespace left
// the engine -- every test died on `ReferenceError: wx is not defined` before
// its first assertion, and the suite reported "0 assertions" rather than a
// failure anyone would read as one. A suite must test the engine's own surface,
// or it tests whichever adapter happened to be loaded.

(() => {
    const PREFIX = "[conformance]";
    const results = [];
    let finished = false;

    const emit = (line) => console.error(PREFIX, line);

    /// Report one assertion. `detail` should carry the numbers, not just a verdict:
    /// a failure that says "expected #ff00ff, got #000000 at (360,640)" is
    /// actionable from a log file on a device you cannot attach a debugger to.
    function check(id, passed, detail) {
        results.push({ id, passed: !!passed });
        emit(`${passed ? "PASS" : "FAIL"} ${id} ${detail || ""}`.trimEnd());
    }

    /// Compare two pixel buffers that must be identical *within this run*.
    ///
    /// This is the reftest primitive, and it is the most valuable one here: it is
    /// platform-independent by construction. Two ways of drawing the same thing
    /// must agree, whatever the GPU does to both of them -- so it survives Mali vs
    /// Adreno vs SwiftShader vs ANGLE, where a golden image cannot.
    function checkSameRender(id, a, b, tolerance) {
        const tol = tolerance || 0;
        if (a.length !== b.length) {
            check(id, false, `buffer lengths differ: ${a.length} vs ${b.length}`);
            return;
        }
        let worst = 0;
        let worstAt = -1;
        for (let i = 0; i < a.length; i++) {
            const d = Math.abs(a[i] - b[i]);
            if (d > worst) { worst = d; worstAt = i; }
        }
        check(
            id,
            worst <= tol,
            worst <= tol
                ? `max channel delta ${worst} <= ${tol}`
                : `max channel delta ${worst} > ${tol} at byte ${worstAt} (px ${Math.floor(worstAt / 4)})`,
        );
    }

    /// Assert one pixel. Sampling beats whole-frame comparison for geometry and
    /// colour: it says which pixel was wrong, and it does not care how the driver
    /// anti-aliased the edge two pixels away.
    function checkPixel(id, ctx, x, y, expected, tolerance) {
        const tol = tolerance === undefined ? 2 : tolerance;
        const px = ctx.getImageData(x, y, 1, 1).data;
        const got = [px[0], px[1], px[2], px[3]];
        const ok = expected.every((want, i) => Math.abs(got[i] - want) <= tol);
        check(id, ok, `at (${x},${y}) want [${expected}] +/-${tol}, got [${got}]`);
    }

    /// End the run. The runner keys off these lines rather than an exit code,
    /// because several of the hosts that must run this suite (a NativeActivity, an
    /// embedded session inside someone else's app) have no exit code to give.
    function done() {
        if (finished) return;
        finished = true;
        const failed = results.filter((r) => !r.passed);
        emit(`SUMMARY total=${results.length} failed=${failed.length}`);
        if (failed.length) emit(`FAILED-IDS ${failed.map((r) => r.id).join(",")}`);
        emit("DONE");
    }

    /// Run test bodies in order, then report. A throw is a failure with the message
    /// attached rather than a silent stop: a suite that dies quietly on one
    /// platform reads exactly like a suite that never ran.
    function run(tests) {
        // One test per frame, not all of them in one turn.
        //
        // Migo batches Canvas2D commands and resolves them at frame
        // boundaries, so a burst of draw-then-getImageData inside a single JS
        // turn is not what any real game does and not what the suite should
        // measure. Driving each test from its own rAF keeps every assertion on
        // the path content actually uses -- and stops the suite reporting
        // engine faults that are really artefacts of its own batching.
        // A body may return a promise, and then the next test does not start
        // until it settles. Lifecycle tests need this and pixel tests do not:
        // "the page went hidden and came back" is an event that arrives when the
        // host decides, not something a test body can drive to completion inside
        // one turn. Awaiting a non-promise is a microtask, so a synchronous body
        // still gets exactly one test per frame and its timing is unchanged --
        // which is why this is safe to add under the existing suites rather than
        // being a second runner they would drift away from.
        let index = 0;
        const step = async () => {
            if (index >= tests.length) {
                done();
                return;
            }
            const [id, body] = tests[index++];
            try {
                await body();
            } catch (error) {
                check(id, false, `threw ${error && error.name}: ${error && error.message}`);
            }
            requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
    }

    // Deliberately a plain script assigned onto the global, not an ES module.
    //
    // Module resolution is exactly the kind of thing that can differ between a
    // bundle loaded by the Android SDK, a C-ABI host, and the Linux player -- and a
    // harness whose own loading is platform-dependent cannot tell you whether the
    // *engine* is platform-dependent. `build.sh` concatenates this ahead of each
    // test, so there is no resolution step at all.

    // Wrapped in an IIFE because build.sh concatenates this ahead of the test
    // in one scope: without it, a test writing `const { check } = ...` collides
    // with the harness's own `check` and the bundle dies at parse time with
    // "Identifier 'check' has already been declared". Caught on the runner's
    // first execution -- by the "no DONE line means failure" rule, which is the
    // one thing standing between this suite and reporting success for a bundle
    // that never ran.
    globalThis.Conformance = { check, checkPixel, checkSameRender, run, done, PREFIX };
})();

// Text: measured, painted, and made to agree with itself.
//
// Nothing here compares against a golden image, because text is the one part of
// Canvas2D where that cannot work: hinting, subpixel positioning and the
// rasteriser's gamma all differ legitimately between Mali, Adreno, SwiftShader
// and Mesa. What does not differ is the engine's own internal consistency --
// that a width scales with the font size, that measuring twice gives the same
// answer, and above all that what `measureText` reports and what `fillText`
// paints come from the same font. So those are what this asserts.
//
// The font ships with the bundle. Measuring the platform's default typeface
// would measure the platform: on Android that is whatever `SkFontMgr_Android`
// resolved for "sans-serif", and it is not the same face the Linux player picks.

const C = globalThis.Conformance;

const canvas = migo.createCanvas();
const ctx = canvas.getContext("2d");
const W = canvas.width;
const H = canvas.height;

// The family the bundle brings with it. `loadFont` returns the canonical name
// the engine registered, which is what has to be used -- not the alias asked
// for, which the engine is free to canonicalise.
const FAMILY = migo.loadFont("vendor/fonts/DejaVuSans.ttf", "conformance-sans");

// Big enough that a glyph is many pixels wide on any of the surfaces this runs
// on, small enough to fit a short string on the narrowest of them.
const SIZE = Math.max(24, Math.min(64, Math.floor(H / 16)));
const BASELINE = Math.floor(SIZE * 1.6);
const SAMPLE = "MMMM";

const clear = () => {
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.fillStyle = "#000000";
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
};

const useFont = (px) => {
    ctx.font = `${px}px "${FAMILY}"`;
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.fillStyle = "#ffffff";
};

/// First and last column, within `[0, limit)` of the row band around the
/// baseline, that the engine put ink in. Reading a band rather than one row is
/// what keeps this independent of where in the glyph the heaviest stroke lands.
const inkExtent = (limit) => {
    const top = Math.max(0, BASELINE - SIZE);
    const height = Math.min(H - top, SIZE + 4);
    const width = Math.min(W, limit);
    const data = ctx.getImageData(0, top, width, height).data;
    let first = -1;
    let last = -1;
    for (let x = 0; x < width; x++) {
        for (let y = 0; y < height; y++) {
            const i = (y * width + x) * 4;
            // Any channel lit at all: anti-aliased edges are faint and still ink.
            if (data[i] > 24 || data[i + 1] > 24 || data[i + 2] > 24) {
                if (first < 0) first = x;
                last = x;
                break;
            }
        }
    }
    return { first, last };
};

C.run([
    ["text/bundled-font-registers", () => {
        C.check(
            "text/bundled-font-registers",
            typeof FAMILY === "string" && FAMILY.length > 0,
            `loadFont returned ${JSON.stringify(FAMILY)}`,
        );
    }],

    ["text/empty-string-has-no-width", () => {
        useFont(SIZE);
        const w = ctx.measureText("").width;
        C.check("text/empty-string-has-no-width", w === 0, `width ${w}`);
    }],

    ["text/width-grows-with-length", () => {
        useFont(SIZE);
        const one = ctx.measureText("M").width;
        const four = ctx.measureText("MMMM").width;
        C.check(
            "text/width-grows-with-length",
            one > 0 && four > one,
            `M=${one}, MMMM=${four}`,
        );
    }],

    ["text/width-scales-with-size", () => {
        useFont(SIZE);
        const small = ctx.measureText(SAMPLE).width;
        useFont(SIZE * 2);
        const large = ctx.measureText(SAMPLE).width;
        const ratio = small > 0 ? large / small : 0;
        // Advance widths are linear in em size. Hinting moves the result by a
        // fraction of a pixel per glyph, not by a fraction of the total.
        C.check(
            "text/width-scales-with-size",
            Math.abs(ratio - 2) <= 0.15,
            `${small} -> ${large}, ratio ${ratio.toFixed(3)} want 2 +/-0.15`,
        );
    }],

    ["text/measure-is-repeatable", () => {
        useFont(SIZE);
        const a = ctx.measureText(SAMPLE).width;
        const b = ctx.measureText(SAMPLE).width;
        // Exact equality on purpose. A width that moves between two calls in
        // one turn means the font the engine measured with changed underneath,
        // which is the failure a cache keyed on the wrong thing produces.
        C.check("text/measure-is-repeatable", a === b, `${a} vs ${b}`);
    }],

    ["text/font-metrics-are-sane", () => {
        useFont(SIZE);
        const m = ctx.measureText(SAMPLE);
        const ascent = m.fontBoundingBoxAscent;
        const descent = m.fontBoundingBoxDescent;
        C.check(
            "text/font-metrics-are-sane",
            ascent > 0 && descent >= 0 && ascent + descent >= SIZE * 0.5,
            `ascent ${ascent}, descent ${descent}, size ${SIZE}`,
        );
    }],

    ["text/fill-text-paints", () => {
        clear();
        useFont(SIZE);
        ctx.fillText(SAMPLE, 10, BASELINE);
        const ink = inkExtent(W);
        C.check(
            "text/fill-text-paints",
            ink.first >= 0 && ink.last > ink.first,
            `ink columns ${ink.first}..${ink.last}`,
        );
    }],

    ["text/fill-text-leaves-the-rest-alone", () => {
        clear();
        useFont(SIZE);
        ctx.fillText(SAMPLE, 10, BASELINE);
        // Far below the baseline, where no descender of this size can reach.
        C.checkPixel(
            "text/fill-text-leaves-the-rest-alone",
            ctx, 10, Math.min(H - 1, BASELINE + SIZE * 2),
            [0, 0, 0, 255],
        );
    }],

    ["text/painted-width-matches-measured", () => {
        clear();
        useFont(SIZE);
        const measured = ctx.measureText(SAMPLE).width;
        ctx.fillText(SAMPLE, 10, BASELINE);
        const ink = inkExtent(W);
        const painted = ink.last - ink.first + 1;
        // The invariant that matters: `measureText` runs on the JS thread and
        // `fillText` shapes on the render thread, and they must be the same
        // font. Ink extent is not advance width -- side bearings and the last
        // glyph's right bearing are legitimately outside it -- so the band is
        // wide. It is still narrow enough to catch the failure it exists for:
        // one side falling back to a different face, which changes the width by
        // much more than bearings do.
        const ok = measured > 0 && painted >= measured * 0.6 && painted <= measured * 1.25;
        C.check(
            "text/painted-width-matches-measured",
            ok,
            `measured ${measured.toFixed(2)}, painted ${painted} (cols ${ink.first}..${ink.last})`,
        );
    }],

    ["text/same-draw-twice-is-identical", () => {
        const box = [0, Math.max(0, BASELINE - SIZE), Math.min(W, 400), Math.min(H, SIZE + 4)];
        clear();
        useFont(SIZE);
        ctx.fillText(SAMPLE, 10, BASELINE);
        const first = ctx.getImageData(box[0], box[1], box[2], box[3]).data;
        clear();
        useFont(SIZE);
        ctx.fillText(SAMPLE, 10, BASELINE);
        const second = ctx.getImageData(box[0], box[1], box[2], box[3]).data;
        C.checkSameRender("text/same-draw-twice-is-identical", first, second, 0);
    }],

    ["text/invalid-font-is-ignored", () => {
        clear();
        useFont(SIZE);
        const before = ctx.font;
        const beforeWidth = ctx.measureText(SAMPLE).width;

        // WHATWG: assigning something that is not a font leaves the previous
        // one in effect. The rule matters here for a reason beyond conformance:
        // the value `ctx.font` holds is what `measureText` measures from, while
        // painting re-parses it on the render thread. If the two disagree about
        // whether a string is a font, the same `ctx.font` measures at one size
        // and paints at another -- silently, and only for content that had a
        // typo in it.
        ctx.font = "definitely not a font";
        C.check(
            "text/invalid-font-is-ignored",
            ctx.font === before,
            `font is ${JSON.stringify(ctx.font)}, want ${JSON.stringify(before)}`,
        );
        C.check(
            "text/invalid-font-does-not-change-metrics",
            ctx.measureText(SAMPLE).width === beforeWidth,
            `width ${ctx.measureText(SAMPLE).width} vs ${beforeWidth}`,
        );

        ctx.fillText(SAMPLE, 10, BASELINE);
        const ink = inkExtent(W);
        const painted = ink.last - ink.first + 1;
        C.check(
            "text/invalid-font-still-paints-what-it-measures",
            painted >= beforeWidth * 0.6 && painted <= beforeWidth * 1.25,
            `measured ${beforeWidth.toFixed(2)}, painted ${painted}`,
        );
    }],

    ["text/align-right-ends-where-asked", () => {
        const anchor = Math.min(W - 1, 400);
        clear();
        useFont(SIZE);
        const measured = ctx.measureText(SAMPLE).width;
        ctx.textAlign = "right";
        ctx.fillText(SAMPLE, anchor, BASELINE);
        const ink = inkExtent(W);
        // The right edge of the ink sits at the anchor, less the last glyph's
        // right side bearing. A quarter of the font size covers that on any
        // face; a left-aligned draw would land a whole string-width away.
        const ok = ink.last >= 0 && anchor - ink.last <= SIZE * 0.25 && ink.first < anchor;
        C.check(
            "text/align-right-ends-where-asked",
            ok,
            `anchor ${anchor}, ink ${ink.first}..${ink.last}, measured ${measured.toFixed(2)}`,
        );
    }],
]);
